def gen(rng):
    def make(n, vmax=10**6):
        # heap-shaped complete tree on n nodes, labels shuffled with the root labelled 0
        labels = list(range(1, n))
        rng.shuffle(labels)
        lab = [0] + labels
        rows = [None] * n
        for i in range(n):
            l = lab[2 * i + 1] if 2 * i + 1 < n else -1
            r = lab[2 * i + 2] if 2 * i + 2 < n else -1
            rows[lab[i]] = f"{rng.randint(1, vmax)} {l} {r}"
        return str(n) + "\n" + "\n".join(rows)

    tests = [make(1), make(2), make(3), make(4), make(5), make(6), make(7), make(8)]
    for n in range(9, 31, 3):
        tests.append(make(n))
    for _ in range(4):
        tests.append(make(rng.randint(10, 25), 5))
    for n in (65535, 65536, 65537, 99999, 100000, 98304, 70000):
        tests.append(make(n))
    return tests

